namespace ghidra.app.util.viewer.field;

using ghidra.app.nav;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.framework.plugintool;
using ghidra.program.util;
using ghidra.program.util;
using ghidra.util;




public class PcodeFieldMouseHandler : FieldMouseHandlerExtension {

	private static Class<object>[] SUPPORTED_CLASSES = new Class[] { typeof(PcodeFieldLocation) };

	/* @Override */
	public bool fieldElementClicked(object clickedObject, Navigatable sourceNavigatable,
			ProgramLocation programLocation, MouseEvent mouseEvent, ServiceProvider serviceProvider) {

		if (mouseEvent.getClickCount() != 2 || mouseEvent.getButton() != MouseEvent.BUTTON1) {
			return false;
		}

		PcodeFieldLocation pcodeLocation = (PcodeFieldLocation) programLocation;
		List<string> pcodeStrings = pcodeLocation.getPcodeStrings();
		int row = pcodeLocation.getRow();
		string pcodeString = pcodeStrings.get(row);
		int column = pcodeLocation.getCharOffset();
		string word = StringUtilities.findWord(pcodeString, column);

		return checkWord(word, serviceProvider, sourceNavigatable);
	}

	protected bool checkWord(string wordString, ServiceProvider serviceProvider,
			Navigatable sourceNavigatable) {

		if (wordString == null) {
			return false;
		}

		ProgramLocation location = sourceNavigatable.getLocation();
		GoToService goToService = serviceProvider.getService(typeof(GoToService));
		if (goToService == null) {
			return false;
		}

		QueryData queryData = new QueryData(wordString, false);
		return goToService.goToQuery(sourceNavigatable, location.getAddress(), queryData, null,
			null);
	}

	/* @Override */
	public Class<object>[] getSupportedProgramLocations() {
		return SUPPORTED_CLASSES;
	}
}
